+// Rounds to the nearest integer, half away from zero (1.5 -> 2, -1.5 -> -2),
+// so refunds (negative amounts) round the same way as the matching charge.
+// `toPrecision` first strips binary floating point noise (e.g. 1.005 * 100
+// === 100.49999999999999) so exact halves don't get rounded down.
+export function roundHalfAwayFromZero(value: number): number {
+  const corrected = Number(value.toPrecision(15));
+  return Math.sign(corrected) * Math.round(Math.abs(corrected));
+}

