+import { addDays, daysBetween } from './dates.ts';
+import type { Invoice } from './invoice.ts';
+
+function dayWord(count: number): string {
+  return count === 1 ? 'day' : 'days';
+}
+
+export function reminderText(invoice: Invoice, termsDays: number, today: Date): string {
+  const dueDate = addDays(invoice.issued, termsDays);
+  const daysUntilDue = daysBetween(today, dueDate);
+
+  if (daysUntilDue > 0) {
+    return `Invoice ${invoice.id} is due in ${daysUntilDue} ${dayWord(daysUntilDue)}`;
+  }
+  if (daysUntilDue === 0) {
+    return `Invoice ${invoice.id} is due today`;
+  }
+  const overdueDays = -daysUntilDue;
+  return `Invoice ${invoice.id} is ${overdueDays} ${dayWord(overdueDays)} overdue`;
+}
