+import { loadLedger, saveLedger } from './storage.ts';
+
+export function cleanLedger(text: string): { text: string; removed: number } {
+  const entries = loadLedger(text);
+  const seen = new Set<string>();
+  const kept = entries.filter(({ category, cents }) => {
+    const key = JSON.stringify([category, cents]);
+    if (cents === 0 || seen.has(key)) return false;
+    seen.add(key);
+    return true;
+  });
+  return { text: saveLedger(kept), removed: entries.length - kept.length };
+}
